package co.edu.uco.seguridad.pdp.assignments.application.usecase.impl;
import co.edu.uco.seguridad.pdp.assignments.application.primaryport.request.ListApplicationAssignmentsPageRequest; import co.edu.uco.seguridad.pdp.assignments.application.primaryport.response.ProfileAssignmentResponse; import co.edu.uco.seguridad.pdp.assignments.application.secondaryport.repository.ProfileAssignmentRepository; import co.edu.uco.seguridad.pdp.assignments.application.usecase.ListApplicationProfileAssignmentsPageUseCase; import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import reactor.core.publisher.Mono;
public final class ListApplicationProfileAssignmentsPageUseCaseImpl implements ListApplicationProfileAssignmentsPageUseCase { private final ProfileAssignmentRepository repository; public ListApplicationProfileAssignmentsPageUseCaseImpl(ProfileAssignmentRepository repository){this.repository=repository;} public Mono<ResultPage<ProfileAssignmentResponse>> execute(ListApplicationAssignmentsPageRequest i){return repository.findPageByApplication(i.tenantId(),i.applicationId(),i.window()).map(p->p.map(a->new ProfileAssignmentResponse(a.id(),a.userId(),a.tenantId(),a.applicationId(),a.profileId(),a.generatedAssignmentIds(),a.validity().validFrom(),a.validity().validUntil())));} }
